import re

_TITLE_RE = re.compile(
    r"<title(?:\s[^>]*)?>(.*?)</title\s*>",
    re.IGNORECASE | re.DOTALL,
)


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in html, or "".

    Tag matching is case-insensitive, and the opening tag may carry
    attributes (e.g. <title lang="en">). The first title element is used.
    Returns "" when there is no complete title element. Surrounding
    whitespace in the title text is stripped. Does not use the network.
    """
    m = _TITLE_RE.search(html)
    if m is None:
        return ""
    return m.group(1).strip()


def test_basic() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>hi</body></html>") == ""


def test_empty_input() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive() -> None:
    assert title_of("<HTML><TITLE>Mixed</Title></HTML>") == "Mixed"


def test_attributes_on_open_tag() -> None:
    assert title_of('<title lang="en">Bonjour</title>') == "Bonjour"


def test_strips_whitespace() -> None:
    assert title_of("<title>\n  Spaced out \n</title>") == "Spaced out"


def test_multiline_title() -> None:
    assert title_of("<title>Line one\nLine two</title>") == "Line one\nLine two"


def test_first_title_wins() -> None:
    assert title_of("<title>A</title><title>B</title>") == "A"


def test_unclosed_title() -> None:
    assert title_of("<title>Never closed") == ""


def test_missing_open_tag() -> None:
    assert title_of("Orphan</title>") == ""


def test_similar_tag_not_matched() -> None:
    assert title_of("<titlebar>nope</titlebar>") == ""


def test_title_in_body_text() -> None:
    assert title_of("<head><title>Real</title></head><body>x</body>") == "Real"

